\begin{enumerate}[label=ii.]
    \item \textbf{ট্রান্সফারেজ (Transferase):} এমন এনজাইমগুলো কোনো সাবস্ট্রেট হতে একটি গ্রুপকে বিচ্ছিন্ন করে অন্য একটি সাবস্ট্রেটের সাথে সংযুক্ত করে। যেমন- কাইনেজ, ট্রান্সঅ্যামাইলেজ ইত্যাদি।
    \begin{equation}
    \text{রাইবুলোজ } 5\text{-ফসফেট} + \text{ATP} \xrightarrow{\text{কাইনেজ}} \text{রাইবুলোজ } 1, 5\text{-বিসফসফেট} + \text{ADP}
    \end{equation}
    \item \textbf{হাইড্রোলেজ (Hydrolase):} এ ধরনের এনজাইম সাবস্ট্রেটকে আর্দ্রবিশ্লেষণ করে। অর্থাৎ, পানির আয়নকে $(\text{H}^+)$ সাবস্ট্রেট এর বিশেষ বন্ধনীর সাথে যুক্ত করে এবং সাবস্ট্রেটকে ভেঙে ফেলে। যেমন- সুক্রেজ, ফসফেটেজ, এস্টারেজ ইত্যাদি।
    \begin{equation}
    \text{সুক্রেজ} + \text{পানি} \xrightarrow{} \text{গ্লুকোজ} + \text{ফুটোজ}
    \end{equation}
    \item \textbf{লাইয়েজ (Lyase):} এসব এনজাইম জারণ-বিজারণ এবং আর্দ্রবিশ্লেষণ ছাড়াই সাবস্ট্রেটের কোনো মূলককে স্থানান্তরিত করে। যেমন- অ্যালাডোলেজ, সাইট্রিক সিন্থেটেজ, ফিউমারেজ ইত্যাদি।
    \begin{equation}
    \text{ফ্রুটোজ } 1, 6\text{-বিসফসফেট} \xrightarrow{\text{অ্যালাডোলেজ}} 3\text{-ফসফোগ্লিসারিনহাইড} + \text{ডাইহাইড্রোক্স অ্যাসিটোন ফসফেট}
    \end{equation}
    \item \textbf{আইসোমারেজ (Isomerase):} এসব এনজাইম জীব পদার্থগুলোকে (সাবস্ট্রেট) আইসোমার গঠনে সাহায্য করে। যেমন- ফসফোগ্লুকো আইসোমারেজ, মিউটেজ।
    \begin{equation}
    \text{গ্লুকোজ } 6\text{-ফসফেট} \xrightarrow{\text{ফসফোগ্লুকোআইসোমারেজ}} \text{ফুটোজ } 6\text{-ফসফেট}
    \end{equation}
    \item \textbf{এপিমারেজ (Epimerase):} এ জাতীয় এনজাইমসমূহ কোনো সাবস্ট্রেটকে তার এপিমারে পরিণত করে। যেমন- এপিমারেজ।
    \begin{equation}
    \text{জাইলুলোজ } 5\text{-ফসফেট} \xrightarrow{\text{এপিমারেজ}} \text{রাইবুলোজ } 5\text{-ফসফেট}
    \end{equation}
    \item \textbf{লাইগেজ (Ligase):} এ জাতীয় এনজাইম ATP-র সহায়তায় দুই বা ততোধিক সাবস্ট্রেটকে যুক্ত করে নতুন যৌগ তৈরি করে। যেমন- গ্লুটামিক সিন্থেটেজ, অ্যাসিটাইল কো-এ সিন্থেটেজ।
